<?php declare(strict_types=1);require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/webhook.php';$merchant=require_login();$pageTitle='Webhooks';$pdo=db();$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='save'){$url=trim((string)($_POST['webhook_url']??''));if($url!==''&&!valid_http_url($url))$notice='Use a valid HTTPS endpoint.';else{$pdo->prepare('UPDATE merchants SET webhook_url=? WHERE id=?')->execute([$url?:null,$merchant['id']]);$notice='Webhook endpoint saved.';}}elseif($action==='retry'){$order=substr((string)($_POST['order_id']??''),0,32);$q=$pdo->prepare("SELECT order_id FROM orders WHERE order_id=? AND merchant_id=? AND status='success'");$q->execute([$order,$merchant['id']]);if($q->fetch()){dispatch_webhook($pdo,$order);$notice='Existing webhook re-sent. Duplicate queue rows are not created.';}else $notice='Order not found or not successful.';}}$q=$pdo->prepare('SELECT webhook_url FROM merchants WHERE id=?');$q->execute([$merchant['id']]);$url=$q->fetchColumn();$health=$pdo->prepare('SELECT l.order_id,l.response_code,l.attempt_count,l.delivered_at FROM webhook_logs l JOIN orders o ON o.order_id=l.order_id WHERE o.merchant_id=? ORDER BY l.id DESC LIMIT 5');$health->execute([$merchant['id']]);$health=$health->fetchAll();
$logs=$pdo->prepare('SELECT l.id,l.order_id,l.response_code,l.attempt_count,l.created_at,l.delivered_at FROM webhook_logs l JOIN orders o ON o.order_id=l.order_id WHERE o.merchant_id=? ORDER BY l.created_at DESC LIMIT 30');$logs->execute([$merchant['id']]);$rows=$logs->fetchAll();require __DIR__.'/includes/dashboard-header.php';?>
<div class="page-title-row" style="margin-bottom:24px"><div><h1>Webhooks</h1><p>Send signed payment events to your HTTPS application endpoint.</p></div></div><?php if($notice):?><div class="note panel"><?=h($notice)?></div><?php endif?><div class="card"><div class="card-title"><h3>Endpoint configuration</h3><span class="badge badge-blue">HMAC-SHA256</span></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save"><div class="field full"><label>Webhook endpoint URL</label><input class="form-input" type="url" name="webhook_url" value="<?=h($url?:'')?>" placeholder="https://your-app.example/webhooks/tg" required></div><div class="field full"><p style="font-size:10px;color:var(--muted);margin:0">Signature header: <code>X-TGGateway-Signature: sha256=&lt;hex&gt;</code>. Verify the raw request body with your API key as the HMAC secret before acting on an event.</p><button class="btn btn-primary">Save endpoint</button></div></form></div><div class="card"><div class="card-title"><h3>Endpoint health</h3><span class="badge badge-blue">Last <?=count($health)?> event(s)</span></div><?php if(!$health):?><p style="font-size:11px;color:var(--muted)">No delivery attempts yet. The first paid order will create one.</p><?php else:?><p style="font-size:11px;color:var(--muted);margin-top:0">A failing endpoint is retried with exponential backoff (5, 10, 20, 40 then 80 minutes) up to five attempts. Payments are never rolled back because a webhook failed; reconcile with <code>GET /api/verify-order.php</code>.</p><ul style="font-size:11px;line-height:1.9;padding-left:18px;margin:0"><?php foreach($health as $failure):?><li><strong><?=h((string)$failure['order_id'])?></strong> — HTTP <?=h((string)($failure['response_code']??'n/a'))?>, <?=h((string)$failure['attempt_count'])?> attempt(s). <?=$failure['delivered_at']?'Delivered':'Awaiting retry'?></li><?php endforeach?></ul><?php endif?></div>
<div class="card"><div class="card-title"><h3>Delivery logs</h3><span style="font-size:10px;color:var(--muted)">Latest 30 attempts</span></div><div class="table-responsive"><table><thead><tr><th>ORDER ID</th><th>HTTP RESPONSE</th><th>ATTEMPTS</th><th>CREATED</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" style="text-align:center;padding:24px;color:var(--muted)">Webhook attempts will appear here after a verified payment.</td></tr><?php endif?><?php foreach($rows as $r):?><tr><td><?=h($r['order_id'])?></td><td><?= $r['response_code']?h((string)$r['response_code']):'—'?></td><td><?=h((string)$r['attempt_count'])?></td><td><?=h(date('M j H:i',strtotime($r['created_at'])))?></td><td><span class="badge <?=$r['delivered_at']?'badge-success':'badge-pending'?>"><?=$r['delivered_at']?'Delivered':'Queued / failed'?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="retry"><input type="hidden" name="order_id" value="<?=h($r['order_id'])?>"><button class="btn btn-secondary" style="padding:5px 9px">Retry</button></form></td></tr><?php endforeach?></tbody></table></div></div><?php require __DIR__.'/includes/dashboard-footer.php';?>